"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[72340],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>l});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},77781:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>a,contentTitle:()=>l,default:()=>k,frontMatter:()=>o,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arrestasjon gjort i SF-drapet p\xe5 Bob Lee - p\xe5st\xe5tt drapsmann jobbet ogs\xe5 innen teknologi","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/nb/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14. april 2023","top_news":"Arrestasjon gjort i SF-drapet p\xe5 Bob Lee - p\xe5st\xe5tt drapsmann jobbet ogs\xe5 innen teknologi"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/nb/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/nb/2023/04/13"}}');var i=n(23420),s=n(3331);const o={localized_date:"14. april 2023",top_news:"Arrestasjon gjort i SF-drapet p\xe5 Bob Lee - p\xe5st\xe5tt drapsmann jobbet ogs\xe5 innen teknologi"},l="2023-04-14",a={},d=[{value:"Arrestasjon gjort i SF-drapet p\xe5 Bob Lee - p\xe5st\xe5tt drapsmann jobbet ogs\xe5 innen teknologi",id:"arrestasjon-gjort-i-sf-drapet-p\xe5-bob-lee---p\xe5st\xe5tt-drapsmann-jobbet-ogs\xe5-innen-teknologi",level:2},{value:"Forbud mot \xe5 v\xe6re vert for YouTube-DL baner vei for privatisert sensur",id:"forbud-mot-\xe5-v\xe6re-vert-for-youtube-dl-baner-vei-for-privatisert-sensur",level:2},{value:"Kunsten \xe5 konstruere biler",id:"kunsten-\xe5-konstruere-biler",level:2},{value:"Apple vil bruke 100 prosent resirkulert kobolt i batterier innen 2025.",id:"apple-vil-bruke-100-prosent-resirkulert-kobolt-i-batterier-innen-2025",level:2},{value:"Vi oppn\xe5dde en 6-dobling av oppstartshastigheten til Podman.",id:"vi-oppn\xe5dde-en-6-dobling-av-oppstartshastigheten-til-podman",level:2},{value:"Forbedre Tailscale via Apples \xe5pne kildekode.",id:"forbedre-tailscale-via-apples-\xe5pne-kildekode",level:2},{value:"Animerte tegninger",id:"animerte-tegninger",level:2},{value:"Amazon CodeWhisperer, gratis for individuell bruk, er n\xe5 generelt tilgjengelig.",id:"amazon-codewhisperer-gratis-for-individuell-bruk-er-n\xe5-generelt-tilgjengelig",level:2},{value:"Google har allerede trukket tilbake seks produkter i 2023.",id:"google-har-allerede-trukket-tilbake-seks-produkter-i-2023",level:2},{value:"Nvidia RTX Remix Runtime Open Source tilgjengelig n\xe5",id:"nvidia-rtx-remix-runtime-open-source-tilgjengelig-n\xe5",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,i.jsx)(r.h2,{id:"arrestasjon-gjort-i-sf-drapet-p\xe5-bob-lee---p\xe5st\xe5tt-drapsmann-jobbet-ogs\xe5-innen-teknologi",children:"Arrestasjon gjort i SF-drapet p\xe5 Bob Lee - p\xe5st\xe5tt drapsmann jobbet ogs\xe5 innen teknologi"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Original"}),".\nEn arrestasjon er gjort i drapet p\xe5 teknologileder Bob Lee, og den p\xe5st\xe5tte drapsmannen jobbet ogs\xe5 innen teknologi og var kjent for Lee. Politiet fant angivelig Lee og den mistenkte kj\xf8rende sammen i en bil registrert p\xe5 den mistenkte, og hevder at en form for konfrontasjon fant sted i bilen og potensielt fortsatte etter at Lee dro. Dekningen av Lees d\xf8d har blitt pakket med andre nylige ulykker og forbrytelser i San Francisco, selv om dette ikke n\xf8yaktig representerer den faktiske levde opplevelsen til de fleste San Franciscans."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nDrapet p\xe5 en teknologileder i San Francisco har utl\xf8st diskusjoner om faktorer som hjeml\xf8shet, mental helse, narkotikamisbruk og fattigdom som kan ha f\xf8rt til forbrytelsen, men kommentatorer advarer mot \xe5 generalisere. Det er ogs\xe5 debatt om bruken av statistikk kontra personlige anekdoter ved vurdering av kriminalitetsrater, og et behov for en tiln\xe6rming som involverer lokalsamfunnet for \xe5 h\xe5ndtere de komplekse problemene med hjeml\xf8shet, avhengighet og kriminalitet. Brukerne fremhever viktigheten av \xe5 vurdere kriminalitetsniv\xe5er i forhold til fattigdom i stedet for \xe5 sammenligne ulike kulturer og ikke trekke forhastede konklusjoner basert p\xe5 ett tilfelle."]}),"\n",(0,i.jsx)(r.h2,{id:"forbud-mot-\xe5-v\xe6re-vert-for-youtube-dl-baner-vei-for-privatisert-sensur",children:"Forbud mot \xe5 v\xe6re vert for YouTube-DL baner vei for privatisert sensur"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Original"}),'.\nEn tysk domstol har d\xf8mt Uberspace ansvarlig for \xe5 v\xe6re vert for nettstedet til youtube-dl - et verkt\xf8y med \xe5pen kildekode som gj\xf8r det mulig \xe5 laste ned YouTube-innhold. Uberspace advarer om at dommen kan f\xf8re til privatisert sensur og anker avgj\xf8relsen, selv om retten mente at Uberspace "kan holdes ansvarlig for \xe5 tvile p\xe5 gyldigheten av en anmodning om fjerning", selv n\xe5r det ikke var klart at verkt\xf8yet br\xf8t loven.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nForbudet mot YouTube-DL-hosting blir sett p\xe5 som et framst\xf8t mot privatisert sensur, der RIAA og MPAA prioriterer penger og makt framfor anstendighet. Immaterielle rettigheters rolle i \xe5 begrense informasjonsflyten debatteres, med en rekke synspunkter, inkludert begrensning av omfang og varighet. Brukere foresl\xe5r alternativer og ford\xf8mmer avhengigheten av GitHub, samtidig som de diskuterer desentralisering og problemer med sikkerhet ved uklarhet i kopibeskyttelse."]}),"\n",(0,i.jsx)(r.h2,{id:"kunsten-\xe5-konstruere-biler",children:"Kunsten \xe5 konstruere biler"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nThe Art of Auto Engineering er et komplett videokurs best\xe5ende av 122+ leksjoner med 20 timer med opptak som forklarer hver eneste del av en bil i detalj, og dekker det grunnleggende til avansert bilteknikk. Kurset ledsages av en 200-siders h\xe5ndbok og er tilgjengelig p\xe5 nettet eller i iOS- og Android-apper for en engangsbetaling p\xe5 25 dollar med livstidstilgang, og er profesjonelt filmet i 4K-kvalitet med full teksting. Kurset roses av seerne for sin engasjerende instruksjon og utmerkede produksjonsverdi."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nBrukere av Hacker News deler erfaringer og anbefaler ressurser for \xe5 l\xe6re om bilteknikk, inkludert interaktive videokurs og spesifikke bilmodeller. Kommentatorer diskuterer fordelene ved \xe5 forst\xe5 bilmekanikk, begrensningene ved \xe5 stole utelukkende p\xe5 AI, og gir tips til gj\xf8r-det-selv-bilreparasjoner. I tillegg diskuterer brukerne nytten av betalte kurs og verkt\xf8y, og noen kritiserer forekomsten av betalingsannonser p\xe5 nettstedet."]}),"\n",(0,i.jsx)(r.h2,{id:"apple-vil-bruke-100-prosent-resirkulert-kobolt-i-batterier-innen-2025",children:"Apple vil bruke 100 prosent resirkulert kobolt i batterier innen 2025."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Original"}),".\nApple har kunngjort sin plan om \xe5 bruke 100 % resirkulert kobolt i alle Apple-designede batterier innen 2025, sammen med fullstendig resirkulerte sjeldne jordartsmetaller for magneter og 100 % resirkulert tinn for kretskort. M\xe5let deres er \xe5 bruke bare resirkulerte og fornybare materialer, og de henter allerede mer enn 95 % av wolfram, nesten tre fjerdedeler av sjeldne jordarter og over to tredjedeler av aluminium fra 100 % resirkulert materiale. Apple bruker utvidet virkelighet (AR) for \xe5 veilede demontering av enheter for resirkuleringspartnere og \xf8ke gjenvinningen av sjeldne jordartsmetaller, og dermed drive frem endringer i hele bransjen for \xe5 redusere avhengigheten av nyutvunnede mineraler."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple kunngjorde sin plan om \xe5 bruke 100 % resirkulert kobolt i batterier innen 2025 og redusere plastavfall, men brukerne diskuterer effekten av disse endringene og om selskapet b\xf8r offentliggj\xf8re sin resirkuleringsteknologi. Debatten om brukerutskiftbare batterier fortsetter, med argumenter om at de er negative for milj\xf8et, mens andre foresl\xe5r at resirkuleringsmetoder og forlenget levetid kan l\xf8se dette problemet. Apples satsing p\xe5 resirkulerbare materialer og en karbonn\xf8ytral forsyningskjede roses, men kritiseres for design og koboltforsyningskjeden. Brukerne diskuterer levetiden til iPhones og Android-telefoner og resirkuleringsmetoder for batterier. Noen brukere foresl\xe5r MagSafe-batterier som prim\xe6rbatteri for iPhones, mens andre stiller sp\xf8rsm\xe5l ved effektiviteten."]}),"\n",(0,i.jsx)(r.h2,{id:"vi-oppn\xe5dde-en-6-dobling-av-oppstartshastigheten-til-podman",children:"Vi oppn\xe5dde en 6-dobling av oppstartshastigheten til Podman."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nRed Hats containermotor, Podman, oppn\xe5dde en 6-dobling av oppstartshastigheten ved \xe5 fjerne un\xf8dvendige prosesser og adressere mindre ineffektivitet som p\xe5virker kritiske applikasjoner som biler, der oppstart av containere i n\xe6r sanntid er avgj\xf8rende. Teamet brukte forbig\xe5ende lagring og ga l\xf8sninger for kjerneproblemer, noe som resulterte i raskere oppstart av containere. Bruken av --transient-store-alternativet er ideelt for edge-enheter, selv om containere med blandet modus ikke st\xf8ttes."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nRed Hats Podman ser en seksdobling av oppstartshastigheten for biler, selv om Discussion Service-brukere diskuterer overkompliseringen av moderne biler og gir uttrykk for bekymring for p\xe5litelighet og vedlikehold. Diskusjonen divergerer i debatter om retten til reparasjon, bruk av mikrotjenester og containere og balansen mellom teknologiske fremskritt og praktisk bruk."]}),"\n",(0,i.jsx)(r.h2,{id:"forbedre-tailscale-via-apples-\xe5pne-kildekode",children:"Forbedre Tailscale via Apples \xe5pne kildekode."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),'.\nTailscale-teamet brukte Apples \xe5pne kildekode for \xe5 feils\xf8ke nettverksgrensesnittrelaterte feil for deres 1.36-utgivelse, og stolte p\xe5 ifconfig for \xe5 bestemme det aktive nettverksgrensesnittet. N\xe5r Tailscale er konfigurert til \xe5 bruke en utgangsnode, blir den standardruten, noe som krever en l\xf8sning for \xe5 konsekvent "binde" nettverksforesp\xf8rsler til det aktive nettverksgrensesnittet uten \xe5 for\xe5rsake sl\xf8yfetrafikk. SIOCGIFDELEGATE, tilgjengelig via ioctl, gj\xf8r det mulig \xe5 oppn\xe5 det underliggende fysiske grensesnittet og ble implementert i Tailscales kode for macOS og iOS.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nDiscussion Service-brukere diskuterer fordelene og utfordringene med programvare med \xe5pen og lukket kildekode i Tailscales forbedring via Apples \xe5pen kildekode. Noen betalingskunder prioriterer omd\xf8mmet til Tailscales kjerneprodukt med \xe5pen kildekode, mens noen tar opp spesifikke problemer med Tailscale, for eksempel vanskeligheter med \xe5 f\xe5 tilgang til nettverksressurser p\xe5 Windows 11 og potensielt batteritap p\xe5 iOS-enheter. Diskusjonen fremhever viktigheten av \xe5 vurdere ulike perspektiver og Tailscales fremgang i forhold til Zerotier p\xe5 grunn av nettverksystemet og den kontinuerlige utrullingen av nye funksjoner, men noen produktbrukere er bekymret for inntektene og vollgraven."]}),"\n",(0,i.jsx)(r.h2,{id:"animerte-tegninger",children:"Animerte tegninger"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),'.\n"Animated Drawings"-depotet p\xe5 Github implementerer algoritmen som er beskrevet i artikkelen "A Method for Automatically Animating Children\'s Drawings of the Human Figure", slik at brukerne kan lage tilpassede animasjoner med sine egne h\xe5ndtegnede figurer. Installasjonsprosessen er enkel, og konfigurasjonsfilene kan endres for \xe5 endre ulike alternativer, inkludert utdataformater og bakgrunnsbilder. Databasen inneholder ogs\xe5 skript og modeller for animering av personlige tegninger, og en nettleserbasert demo er tilgjengelig for rask og enkel bruk.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nFair Animated Drawings-prosjektet animerer tegninger med kode, tilgjengelig i en nettleserbasert versjon og en GitHub-versjon. Brukerne er interessert i potensialet for forretningsideer og h\xe5per p\xe5 en Android-appversjon. Et relevant arbeid om ikke-fotorealistisk poseringsestimering kalt Gesture3D ser ut til \xe5 v\xe6re aktuelt for et bestemt bruksomr\xe5de, og YC Summer 2023-s\xf8knadene er \xe5pne."]}),"\n",(0,i.jsx)(r.h2,{id:"amazon-codewhisperer-gratis-for-individuell-bruk-er-n\xe5-generelt-tilgjengelig",children:"Amazon CodeWhisperer, gratis for individuell bruk, er n\xe5 generelt tilgjengelig."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, en sanntids AI-kodingsledsager, er n\xe5 generelt tilgjengelig og inkluderer et CodeWhisperer Individual-niv\xe5 som er gratis for alle utviklere \xe5 bruke. Verkt\xf8yet hjelper utviklere med \xe5 skrive kode raskt og sikkert og uten \xe5 forlate IDE-en sin. CodeWhisperer tilbyr forslag til generelle brukstilfeller p\xe5 tvers av en rekke spr\xe5k og kan filtrere eller flagge kodeforslag som kan ligne p\xe5 bestemte treningsdata med \xe5pen kildekode, noe som bidrar til \xe5 redusere risikoen for \xe5 bruke potensielt partisk eller feilaktig kode."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer er n\xe5 generelt tilgjengelig og st\xf8tter flere spr\xe5k, inkludert Python, Java, JavaScript, TypeScript og C#. Selv om Copilot angivelig er bedre enn CodeWhisperer, er sistnevnte et nyttig verkt\xf8y som kan f\xf8re til at AI-genererte koder blir normen. I tillegg har Amazon lansert CodeGuru Reviewer, et AI-verkt\xf8y som skanner kode for \xe5 identifisere problemer og anbefale l\xf8sninger for effektivitet og kostnadsreduksjon."]}),"\n",(0,i.jsx)(r.h2,{id:"google-har-allerede-trukket-tilbake-seks-produkter-i-2023",children:"Google har allerede trukket tilbake seks produkter i 2023."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle har lagt ned seks produkter i l\xf8pet av de f\xf8rste fire m\xe5nedene av 2023, inkludert programmeringskonkurransen Code Jam, den sosiale medieplattformen Google Currents, Street View-appen, den b\xe6rbare teknologien Google Jacquard, skyspilltjenesten Google Stadia og den tr\xe5dl\xf8se ruteren Google OnHub. Selv om noen av disse produktene var over ti \xe5r gamle, har Google f\xe5tt kritikk for sin vane med \xe5 br\xe5tt avslutte popul\xe6re tjenester."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle har avviklet seks produkter i 2023, med bekymringer om \xe5penhet og produktmerking, og manglende st\xf8tte til mislykkede fors\xf8k, inkludert Google Glass og Google Plus. Skyenheten vokser med en markedsandel p\xe5 10 %, men det er bekymringer knyttet til kunde- og utviklerengasjement og algoritmen som dreper kontoer. Brukerne diskuterer l\xf8sninger og kostnader for \xe5 forbedre ChatGPTs n\xf8yaktighet, mens Googles rykte for \xe5 skrinlegge prosjekter f\xf8rer til kritikk av produktst\xf8tten til forbrukerne."]}),"\n",(0,i.jsx)(r.h2,{id:"nvidia-rtx-remix-runtime-open-source-tilgjengelig-n\xe5",children:"Nvidia RTX Remix Runtime Open Source tilgjengelig n\xe5"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia har gitt ut RTX Remix runtime, en \xe5pen kildekode-moddingsplattform for remastering av klassiske DirectX 8- og 9-spill med banesporing, AI-forbedrede teksturer og brukeropprettede eiendeler. RTX Remix Creator-verkt\xf8ysettet gj\xf8r det mulig for moddere \xe5 tilordne nye ressurser og lys i en remastret scene, og bruke AI-verkt\xf8y til \xe5 gjenoppbygge utseendet til en hvilken som helst ressurs. RTX Remix-kj\xf8retiden, derimot, fanger en spillscene, erstatter ressurser ved avspilling og injiserer RTX-teknologi, for eksempel banesporing, DLSS 3 og Reflex i spillet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia har gitt ut sin RTX Remix Runtime med \xe5pen kildekode, slik at brukerne kan spille eldre spill med str\xe5lesporing i sanntid, selv om ikke alle spill vil fungere. Hacker News-brukere diskuterer viktigheten av drivere med \xe5pen kildekode versus propriet\xe6re drivere, Nvidias omd\xf8mme og den d\xe5rlige ytelsen til RTX p\xe5 maskinvare som ikke er Nvidia. Brukere spekulerer ogs\xe5 i potensiell favorisering og foresl\xe5r \xe5 st\xf8tte kryptovalutautviklere som implementerer GPU-bare proof-of-work-ordninger. En bruker bemerker Remedys utvikling av nyinnspillinger av Max Payne PC-spill ved hjelp av Remix og diskuterer teknologiens rammehastighet og problemer med stamming."]})]})}function k(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(g,{...e})}):g(e)}}}]);